def backup(path):
    dest = path.with_suffix(path.suffix + ".bak-v7")
    if not dest.exists():
        shutil.copy2(path, dest)

def apply_replacements(path, replacements):
    text = path.read_text()
    backup(path)
    for old, new, expected, label in replacements:
        count = text.count(old)
        if count != expected:
            raise RuntimeError(
                f"{label}: expected {expected} match(es), found {count}"
            )
        text = text.replace(old, new)
    path.write_text(text)

def write_new_files():
    for relative, content in NEW_FILES.items():
        path = ROOT / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        if path.exists():
            raise RuntimeError(
                f"Refusing to overwrite existing file: {relative}"
            )
        path.write_text(content)
        if path.suffix == ".sh" or path.name == "speaker_identity.py":
            path.chmod(0o755)

def patch_gitignore():
    path = ROOT / ".gitignore"
    text = path.read_text()
    backup(path)
    if "/models/" not in text:
        if not text.endswith("\n"):
            text += "\n"
        text += "/models/\n"
    if "*.bak-v7" not in text:
        text += "*.bak-v7\n"
    path.write_text(text)

def main():
    required = [
        ROOT / "pi" / "talking_box.py",
        ROOT / "server" / "main.py",
        ROOT / ".gitignore",
    ]
    missing = [str(p) for p in required if not p.exists()]
    if missing:
        print("Run this from the talking-box repo root.", file=sys.stderr)
        print("Missing:", *missing, sep="\n  ", file=sys.stderr)
        return 2

    try:
        write_new_files()
        apply_replacements(ROOT / "pi" / "talking_box.py", PI_REPLACEMENTS)
        apply_replacements(ROOT / "server" / "main.py", SERVER_REPLACEMENTS)
        patch_gitignore()
    except Exception as exc:
        print(
            f"V7 patch failed: {type(exc).__name__}: {exc}",
            file=sys.stderr,
        )
        print(
            "Existing-file backups use .bak-v7. "
            "New files may have been created.",
            file=sys.stderr,
        )
        return 1

    print("V7 speaker-ID integration applied.")
    print()
    print("Review:")
    print("  git diff")
    print()
    print("Then on the Pi:")
    print("  ./pi/setup-speaker-id.sh")
    print('  ./pi/enroll-speaker.sh jesse "Jesse"')
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
